    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be printed in full (doctor output is pasted into tickets).
SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}


def _unquote(value):
    """Strip one matching pair of surrounding quotes. Single quotes are literal;
    double quotes also honour backslash escapes for \\" and \\\\."""
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        inner = value[1:-1]
        if value[0] == '"':
            inner = inner.replace('\\"', '"').replace("\\\\", "\\")
        return inner
    return value


def _parse_line(line):
    """Return (key, value) for a KEY=VALUE line, or None for blank, comment or malformed lines."""
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    if line.startswith("export ") or line.startswith("export\t"):
        line = line[len("export"):].lstrip()
    if "=" not in line:
        return None
    key, value = line.split("=", 1)
    key = key.strip()
    if not key:
        return None
    return key, _unquote(value.strip())


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = _parse_line(line)
            if parsed is not None:
                key, value = parsed
                values[key] = value
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def _display_value(key, value):
    if value is None:
        return "<not set>"
    if key in SECRET_KEYS:
        return f"<redacted, {len(value)} chars>"
    return value


def doctor_report(environ=None, dotenv_path=".env"):
    """Return the human-readable configuration report printed by `python -m payhook doctor`."""
    environ = os.environ if environ is None else environ
    config = load_config(environ=environ, dotenv_path=dotenv_path)
    lines = [
        "payhook configuration",
        f"dotenv file: {os.path.abspath(dotenv_path)} "
        f"({'found' if os.path.exists(dotenv_path) else 'not found'})",
        "",
    ]
    width = max(len(key) for key in config)
    for key, (value, source) in config.items():
        shown = _display_value(key, value)
        lines.append(f"{key.ljust(width)} = {shown}  [source: {source}]")
    missing = [k for k, (v, _) in config.items() if v is None]
    lines.append("")
    lines.append("missing required: " + ", ".join(missing) if missing else "missing required: none")
    return "\n".join(lines)

